css:
:host{--bg:#050605;--bg2:#0C0F0D;--panel:#111512;--line:#232826;--green:#00FF66;--ink:#EEF1EC;--muted:#A4A6AA;--lav:#C0B0EF;--purple:#3401CC;--dark:#050605;}
section{background:var(--bg);color:var(--ink);font-family:'Plus Jakarta Sans',sans-serif;padding:128px 128px 160px;counter-increment:page;display:flex;flex-direction:column;}
section.alt{background:var(--bg2);}
.g{color:var(--green);}
.kicker{font-size:24px;font-weight:700;letter-spacing:4px;text-transform:uppercase;color:var(--green);margin:0 0 14px;}
.kicker.dark{color:var(--dark);}
h2{font-size:64px;font-weight:800;line-height:1.1;letter-spacing:-1px;margin:0 0 48px;color:var(--ink);}
h3{font-size:36px;font-weight:700;line-height:1.2;margin:0 0 10px;color:var(--ink);}
.footer{position:absolute;left:128px;bottom:56px;width:1664px;height:40px;display:flex;align-items:center;justify-content:space-between;}
.footer img{width:115px;height:29px;object-fit:contain;}
.footer p{font-size:24px;color:var(--muted);margin:0;}
.pnum{font-size:24px;color:var(--green);font-weight:700;width:60px;text-align:right;}
.pnum::after{content:counter(page);}
.split{display:grid;grid-template-columns:1fr 1.3fr;gap:64px;align-items:start;}
.split.wide{grid-template-columns:1fr 1.75fr;}
.two{display:grid;grid-template-columns:1fr 1fr;gap:40px;align-items:start;}
ul.pts{font-size:30px;line-height:1.4;padding-left:36px;margin:0;color:var(--ink);}
ul.pts li{margin:0 0 20px;}
.codebox{display:flex;flex-direction:column;background:var(--panel);border:2px solid var(--line);border-radius:20px;overflow:hidden;}
.fname{font-family:'JetBrains Mono',monospace;font-size:24px;color:var(--muted);margin:0;padding:14px 36px;background:#181D1A;border-bottom:2px solid var(--line);}
.code{font-family:'JetBrains Mono',monospace;font-size:24px;line-height:1.48;color:var(--ink);margin:0;padding:24px 36px;}
.code.tight{line-height:1.34;}
.code.sm{background:var(--panel);border:2px solid var(--line);border-radius:16px;padding:20px 28px;line-height:1.45;}
.code .k{color:var(--lav);} .code .s{color:#6BFF6B;} .code .c{color:#7E848A;} .code .n{color:#FFC46B;}
.inline-code{font-family:'JetBrains Mono',monospace;font-size:24px;line-height:1.5;color:var(--green);background:var(--panel);border:2px solid var(--line);border-radius:14px;padding:16px 24px;margin:8px 0 0;}
@keyframes rise{from{opacity:0;transform:translateY(24px);}to{opacity:1;transform:translateY(0px);}}
.stagger > *{animation:rise 520ms ease-out both;}
.stagger > *:nth-child(2){animation-delay:110ms;} .stagger > *:nth-child(3){animation-delay:220ms;} .stagger > *:nth-child(4){animation-delay:330ms;} .stagger > *:nth-child(5){animation-delay:440ms;} .stagger > *:nth-child(6){animation-delay:550ms;} .stagger > *:nth-child(7){animation-delay:640ms;} .stagger > *:nth-child(8){animation-delay:720ms;}
/* cover */
section.cover{padding:128px;justify-content:space-between;}
.glow{position:absolute;left:-520px;top:520px;width:1200px;height:1200px;}
.cover-logo{width:230px;height:58px;}
.cover-main{display:flex;flex-direction:column;width:1080px;}
.pill{align-self:flex-start;font-size:24px;font-weight:600;color:var(--ink);background:#141816;border:2px solid var(--line);border-radius:999px;padding:10px 24px;margin:0 0 32px;}
h1{font-size:96px;font-weight:800;line-height:1.05;letter-spacing:-2px;margin:0 0 32px;}
.cover-sub{font-size:32px;line-height:1.45;color:var(--muted);margin:0 0 40px;width:960px;}
.cover-tutor{font-size:28px;color:var(--ink);margin:0;}
.tile{position:absolute;left:1280px;top:300px;width:420px;height:420px;background:var(--green);border-radius:72px;transform:rotate(8deg);box-shadow:0 0 140px rgba(0,255,102,0.45);display:flex;align-items:center;justify-content:center;animation:tilein 700ms ease-out both;}
@keyframes tilein{from{opacity:0;transform:rotate(-6deg) scale(0.85);}to{opacity:1;transform:rotate(8deg) scale(1);}}
.tile svg.xi{color:var(--dark);width:220px;height:220px;}
/* tutor */
.tutor-grid{display:grid;grid-template-columns:600px 1fr;gap:80px;align-items:center;flex:1;}
.photo{width:600px;height:700px;object-fit:cover;border-radius:32px;border:3px solid var(--green);box-shadow:0 0 80px rgba(0,255,102,0.25);}
section.tutor{padding:100px 128px 160px;}
.tname{font-size:88px;letter-spacing:-2px;margin:0 0 12px;}
.handle{font-size:32px;color:var(--green);font-weight:700;margin:0 0 8px;}
.role{font-size:28px;color:var(--muted);margin:0 0 40px;}
/* agenda */
.tgrid{display:grid;grid-template-columns:1fr 1fr 1fr 1fr;gap:24px;}
.tcard{background:var(--panel);border:2px solid var(--line);border-radius:20px;padding:28px;}
.tnum{font-family:'JetBrains Mono',monospace;font-size:28px;color:var(--green);font-weight:700;margin:0 0 12px;}
.ttl{font-size:30px;font-weight:700;line-height:1.3;margin:0;}
.buildline{font-size:30px;color:var(--ink);margin:48px 0 0;background:rgba(0,255,102,0.08);border-left:6px solid var(--green);padding:20px 28px;}
.buildline b{color:var(--green);}
/* statements */
section.statement{background:var(--green);color:var(--dark);justify-content:center;}
section.statement .footer p{color:#0B3B1D;} section.statement .pnum{color:var(--dark);}
.big{font-size:104px;font-weight:800;line-height:1.05;letter-spacing:-3px;margin:0 0 40px;width:1500px;color:var(--dark);}
.bigsub{font-size:36px;line-height:1.4;margin:0;width:1300px;color:#0B2A16;font-weight:500;}
.qa{font-size:44px;font-weight:800;margin:72px 0 0;color:var(--dark);}
section.statement2{background:var(--bg2);}
/* web flow */
.flow{display:flex;align-items:center;gap:24px;}
.node{flex:1;background:var(--panel);border:2px solid var(--line);border-radius:24px;padding:36px;display:flex;flex-direction:column;}
.node.hot{border-color:var(--green);box-shadow:0 0 60px rgba(0,255,102,0.2);}
.node svg.xi{color:var(--green);width:64px;height:64px;margin:0 0 20px;}
.node p{font-size:28px;line-height:1.4;color:var(--muted);margin:0;}
.arrows{width:150px;display:flex;flex-direction:column;align-items:center;gap:10px;}
.al{font-size:24px;font-weight:700;margin:0;} .al.g{color:var(--green);} .al.l{color:var(--lav);}
.ar1{width:110px;height:44px;background:var(--green);} .ar2{width:110px;height:44px;background:var(--lav);}
.example{font-family:'JetBrains Mono',monospace;font-size:28px;color:var(--green);margin:56px 0 0;background:var(--panel);border:2px solid var(--line);border-radius:16px;padding:22px 32px;}
/* req res */
.codes{display:flex;gap:16px;margin:32px 0 0;}
.sc{font-family:'JetBrains Mono',monospace;font-size:24px;margin:0;padding:10px 20px;border-radius:999px;background:rgba(0,255,102,0.12);color:var(--green);}
.sc.bad{background:rgba(192,176,239,0.14);color:var(--lav);}
/* tools */
.tools{display:grid;grid-template-columns:1fr 1fr 1fr;gap:32px;}
.tool,.bcard{background:var(--panel);border:2px solid var(--line);border-radius:24px;padding:40px;display:flex;flex-direction:column;}
.tool svg.xi{color:var(--green);width:64px;height:64px;margin:0 0 24px;}
.td{font-size:28px;line-height:1.4;color:var(--muted);margin:0 0 28px;}
.tcode{font-family:'JetBrains Mono',monospace;font-size:24px;line-height:1.6;color:var(--green);background:#0A0D0B;border-radius:12px;padding:16px 20px;margin:0;}
.mono{font-family:'JetBrains Mono',monospace;color:var(--green);}
.uses{font-size:24px;color:var(--lav);margin:0;line-height:1.4;}
/* arrays */
.methods{display:flex;flex-direction:column;gap:20px;}
.m{border-left:6px solid var(--green);padding:6px 0 6px 24px;}
.mn{font-family:'JetBrains Mono',monospace;font-size:32px;color:var(--green);font-weight:700;margin:0 0 4px;}
.md{font-size:28px;line-height:1.4;color:var(--muted);margin:0;}
/* modern */
.mrows{display:flex;flex-direction:column;gap:28px;}
.mrow{display:grid;grid-template-columns:520px 1fr;gap:48px;align-items:center;}
/* recap */
.panel{background:var(--panel);border:2px solid var(--line);border-radius:24px;padding:40px;}
.panel.hot{border-color:var(--green);}
.panel h3{color:var(--green);margin:0 0 24px;}
ul.checks,ol.hw{font-size:28px;line-height:1.4;margin:0;padding-left:36px;}
ul.checks li,ol.hw li{margin:0 0 16px;}

.bm-margin{position:relative;border:3px dashed #FFC46B;border-radius:24px;padding:44px 36px 36px;}
.bm-border{position:relative;border:6px solid #00FF66;border-radius:18px;padding:44px 32px 32px;}
.bm-padding{position:relative;background:rgba(192,176,239,0.16);border-radius:10px;padding:44px 32px 32px;}
.bm-content{background:#EEF1EC;border-radius:8px;padding:24px;display:flex;justify-content:center;}
.bm-content p{font-size:28px;font-weight:700;color:#050605;margin:0;}
.bm-l{position:absolute;left:24px;top:6px;font-family:'JetBrains Mono',monospace;font-size:24px;color:#FFC46B;margin:0;}
.bm-l.g{color:#00FF66;} .bm-l.l{color:#C0B0EF;}
.bm-cap{font-size:28px;line-height:1.4;color:#A4A6AA;margin:28px 0 0;}
.fdemo{display:flex;align-items:center;gap:16px;margin:36px 0 0;padding:20px;border:2px dashed #232826;border-radius:16px;}
.fdemo div{font-size:24px;font-weight:700;color:#050605;background:#00FF66;border-radius:10px;padding:10px 18px;}
.fdemo div.sp{flex:1;background:none;padding:0;}
.gdemo{display:grid;grid-template-columns:1fr 1fr 1fr;gap:14px;margin:36px 0 0;padding:20px;border:2px dashed #232826;border-radius:16px;}
.gdemo div{font-size:28px;font-weight:800;color:#050605;background:#C0B0EF;border-radius:10px;padding:18px;text-align:center;}
.bcard h3{color:#EEF1EC;}

.steps{display:flex;flex-direction:column;gap:14px;}
.step{display:grid;grid-template-columns:72px 1fr;gap:24px;align-items:start;background:#111512;border:2px solid #232826;border-radius:20px;padding:16px 26px;}
.step .sn{width:56px;height:56px;border-radius:16px;background:#00FF66;color:#050605;font-size:28px;font-weight:800;display:flex;align-items:center;justify-content:center;margin:0;}
.step h3{margin:0 0 2px;font-size:30px;}
.step p{margin:0;font-size:24px;line-height:1.4;color:#A4A6AA;}
.tgrid.nine{grid-template-columns:1fr 1fr 1fr;gap:18px;}
.tgrid.nine .tcard{padding:20px 24px;}
.tgrid.nine .ttl{font-size:28px;}
.tgrid.nine .tnum{margin:0 0 6px;}
.tool .tcode{font-size:24px;}
.two.wideleft{grid-template-columns:1.1fr 1fr;}

.pnum::after{content:none;}
.ar1,.ar2{background:none;}
section{width:1920px;height:1080px;box-sizing:border-box;position:relative;overflow:hidden;}
.glow{z-index:0;}.cover-logo,.cover-main{position:relative;z-index:1;}
